prompt --application/shared_components/logic/application_processes/set_language
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(60002100000430)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_LANGUAGE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_lang varchar2(2) := case :REQUEST when ''LANG_AR'' then ''ar'' else ''en'' end;',
'begin',
'  lms_user_pkg.set_language(l_lang);',
'  apex_util.set_session_lang(l_lang);',
'  :LMS_LANG := l_lang;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'LANG_AR,LANG_EN'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_version_scn=>1
);
end;
