'  end loop;',
'  htp.p(''<nav class="lms-steps" aria-label="Course builder steps">'' || case when 11 = 11 then ''<strong>1. Basic information</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 11, p_items => ''P11_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">1. Basic information</a>'' end || '' &rsaquo; '' || case when 12 = 11 then ''<strong>2. Modules</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 12, p_items => ''P12_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">2. Modules</a>'' end || '' &rsaquo; '' || case when 13 = 11 then ''<strong>3. Lessons</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 13, p_items => ''P13_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">3. Lessons</a>'' end || '' &rsaquo; '' || case when 14 = 11 then ''<strong>4. Assessments</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 14, p_items => ''P14_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">4. Assessments</a>'' '||'end || '' &rsaquo; '' || case when 15 = 11 then ''<strong>5. Completion rules</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 15, p_items => ''P15_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">5. Completion rules</a>'' end || '' &rsaquo; '' || case when 16 = 11 then ''<strong>6. Review and publish</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 16, p_items => ''P16_COURSE_ID'', p_values => :P11_COURSE_ID) || ''">6. Review and publish</a>'' end || ''</nav>'');',
'end if;'))
